about:"Bengal kaplanı dünyadaki en tanınmış kaplan alt türlerinden biridir.",
behavior:"Bengal kaplanları genellikle yalnız yaşayan ve kendi bölgelerini koruyan hayvanlardır. Dişi kaplanlar yavrularıyla birlikte yaşarken, erkekler daha geniş alanları kontrol eder. Çoğunlukla gece avlanan bu güçlü yırtıcılar, avlarını sessizce takip edip pusu kurarak yakalarlar. Kaplanlar aynı zamanda çok iyi yüzücülerdir ve sıcak havalarda suya girerek serinlemeyi severler. Kükrme, hırlama ve homurtu gibi çeşitli sesler çıkararak diğer kaplanlarla iletişim kurarlar. Güçlü çeneleri ve kaslı yapıları sayesinde büyük avları bile kolaylıkla etkisiz hale getirebilirler.",
distribution:"Günümüzde Bengal kaplanları Hindistan, Bangladeş, Nepal, Bhutan ve güneybatı Çin'de bulunmaktadır. Tropikal nemli yaprak dökmeyen ormanlar, tropikal kuru ormanlar, tropikal ve subtropikal nemli yaprak döken ormanlar, mangrovlar, subtropikal ve ılıman yüksek rakımlı ormanlar, taşkın ovaları ve alüvyal otlaklarda yaşarlar. ",
facts:[
"Bengal kaplanları kısa mesafelerde saatte 64 kilometreye kadar hızla koşabilir ve 5 metreye kadar havaya sıçrayabilirler.",
"Her bireyin çizgi deseni farklıdır.",
"Geceleri çok iyi görebilirler.",
"Hayvanlar arasında en iyi hafızaya sahip olanlardan biridirler; kısa süreli hafızaları insanlardan bile daha uzun sürer.",
"Dünyanın en büyük kedileri arasındadır.",
"Güçlü çene yapılarıyla tanınırlar."
],
