behavior:"Kızıl tilkiler genellikle aile grupları halinde yaşayan sosyal hayvanlardır. Gruplar çoğunlukla bir erkek, bir veya iki dişi ve yavrularından oluşur. Yuvalarını toprak altına yaparlar ve aynı yuva nesiller boyunca kullanılabilir. Kızıl tilkiler en çok gün doğumundan önce ve akşam saatlerinde aktif olur, avlarını ise genellikle yalnız avlarlar. Güçlü işitme duyuları sayesinde avlarının yerini kolayca tespit edebilir ve ani sıçrayışlarla yakalayabilirler. Oldukça geniş bir ses repertuarına sahip olan kızıl tilkiler; havlama, cıvıldama ve uzun uluma benzeri seslerle iletişim kurarlar. Tehlike anında kısa havlamalarla birbirlerini uyarabilirler.",
