distribution:"Mirketler, Güney Afrika'da Angola'nın en güneybatısından başlayarak Namibya ve Botsvana üzerinden Güney Afrika'nın batı ve kuzeyine kadar geniş bir dağılıma sahiptir. Çeşitli kurak, açık alanlarda, az ağaçlıklı bitki örtüsüne sahip, taşlı ve genellikle kireçli topraklarda yaşarlar. Mirketler savanlarda, açık ovalarda ve kuru nehirlerin kenarındaki kayalık alanlarda yaygındır.",
