behavior:"Mavi maymunlar gündüz aktif olan ve oldukça sosyal primatlardır. Genellikle bir erkek, birçok dişi ve yavrularından oluşan 10-40 bireylik gruplar halinde yaşarlar. Dişiler doğdukları grupta kalırken, erkekler olgunlaştıklarında yeni gruplara katılmak için ayrılırlar. Ağaçlarda yaşayan bu maymunlar, zamanlarının büyük bölümünü beslenerek, oyun oynayarak ve birbirlerini tımar ederek geçirirler. Mavi maymunlar oldukça bölgecidir ve yaşam alanlarını diğer gruplara karşı korurlar. Grup içindeki sosyal ilişkiler güçlüdür ve bireyler sürekli iletişim halindedir. Yeni bir bireyin gruba katılması genellikle baskın erkekle yaşanan rekabet sonucunda mümkün olur.",
distribution:"Mavi maymunların doğal yaşam alanı oldukça geniştir ve Orta, Doğu ve Güney Afrika'nın yanı sıra Kongo havzasını da kapsar. Bu yaşam alanı içinde mavi maymunlar nemli ve gölgeli alanlarda yaşarlar. Sürekli su kaynağı, en önemli gereksinimler arasındadır. Genel olarak tercih edilen yaşam alanları her daim yeşil ormanlar, orman örtüsü ve bambu ormanlarıdır.",
facts:[
"Uzun kuyrukları denge sağlar.",
"Mavi maymun, alnında taç benzeri, beyazımsı veya sarımsı bir işaret bulunduğu için 'Taçlı maymun' olarak da adlandırılır.",
"Sosyal gruplar oluştururlar.",
"Karşılıklı tüy temizleme, bu maymunlar için önemli bir faaliyettir; bu sayede birbirlerine sevgi gösterir ve aralarındaki barışı sağlarlar.",
"Farklı seslerle iletişim kurarlar.",
"Maymunlar, esneme, baş sallama, dudak büzme veya çekme gibi çeşitli şekillerde saldırganlık gösterirler; ayrıca başlarını ve omuzlarını öne doğru ani hareketlerle ani hareketler yaparlar.",
"Hızlı hareket edebilirler."
],
lifespan:"20 - 30 yıl",
