"Dinlenirken çizgili yunuslar asla tamamen uykuya dalmazlar: zaman zaman nefes almak için su yüzüne çıkmak ve olası tehditlere karşı kendilerini savunmak için her zaman kısmen bilinçli kalırlar.",
