behavior:"Gri kurtlar son derece sosyal hayvanlardır ve sürüler halinde yaşar, avlanır ve hareket ederler. Bir sürü genellikle lider bir erkek ve dişinin yanı sıra yavrular ve genç bireylerden oluşur. Sürü üyeleri arasında güçlü bağlar bulunur ve havlama, uluma, hırlama ve inleme gibi çeşitli seslerle iletişim kurarlar. Çoğunlukla gece aktif olan kurtlar, avlarını takip etmek için geniş bölgelerde dolaşır ve uzun mesafeler kat edebilirler. Avlanırken ekip halinde hareket ederek iş birliği yaparlar ve bu sayede kendilerinden daha büyük hayvanları bile avlayabilirler. Gri kurtlar yılın belirli dönemlerinde yerleşik bir yaşam sürerken, bazı dönemlerde yiyecek arayışıyla daha göçebe bir yaşam tarzı benimserler. Zekâları, güçlü sosyal yapıları ve etkili iletişim becerileri sayesinde doğanın en başarılı yırtıcılarından biri olarak kabul edilirler.",
distribution:"Gri kurtlar Kuzey Amerika ve Avrasya'da, özellikle ücra bölgelerde ve vahşi doğada yaygın olarak bulunur. Bu hayvanlar ormanlarda, iç kesimlerdeki sulak alanlarda, çalılık alanlarda, otlaklarda (Arktik tundra dahil), meralarda, çöllerde ve dağlardaki kayalık zirvelerde yaşarlar.",
