distribution:"Kahverengi ayılar, Kuzey Amerika'dan Batı Avrupa'ya, Filistin'e, Doğu Sibirya'ya ve Himalayalar bölgesine kadar çok az sayıda bulunur. Bu hayvanların yaşam alanı genellikle nehir kenarlarıdır. Çayırlar, dağ çayırları, ağaçlık alanlar ve ormanlardaki nehir ve derelerin kenarlarında yaşamayı tercih ederler.",
