behavior:"Kuzey Sumatra gergedanları genellikle yalnız yaşayan ve kendi bölgelerini koruyan hayvanlardır. Erkeklerin yaşam alanları zaman zaman örtüşebilse de dişiler genellikle ayrı bölgelerde yaşarlar. Bölgelerini toprağı eşeleyerek, ağaçları işaretleyerek ve dışkı bırakarak belirlerler. En çok şafak vakti ve gün batımından sonra aktif olur, günün sıcak saatlerinde ise çamur banyolarında dinlenirler. Çamur banyoları, vücut sıcaklıklarını düzenlemelerine ve derilerini parazitlerden korumalarına yardımcı olur. Yağışlı dönemlerde yüksek rakımlara çıkarken, daha serin dönemlerde alçak bölgelere inerler. Güçlü ve çevik yapıları sayesinde dik yamaçlara kolayca tırmanabilir ve nehirleri rahatlıkla geçebilirler. Ayrıca ciyaklama, ıslık ve balina sesine benzeyen çağrılar çıkararak iletişim kuran, en sesli gergedan türlerinden biridir.",
distribution:"Endonezya'nın Sumatra Adası'nda yaşamaktaydılar. Kuzey Sumatra gergedanları tropikal yağmur ormanlarında, bataklıklarda, bulut ormanlarında, ormanlarda ve otlaklarda yaşamaktaydı. Ayrıca tepelik alanlarda, nehir kenarlarında, dik vadilerde ve dağlarda da yaşamaktaydılar.",
