distribution:"Bonobo, yalnızca Orta Afrika'da, Demokratik Kongo Cumhuriyeti'nde, kuzeyde Kongo Nehri, güney ve batıda Kasai Nehri ve doğuda Lualaba Nehri ile çevrili bir bölgede yaşar. Bonobolar, dünyanın ikinci büyük yağmur ormanı olan Kongo Havzası'nın ortasında yaşarlar.",
