"Mavi alakargalar insan konuşmasını taklit etmeyi öğrenebilirler. Ayrıca yerel şahinlerin seslerini o kadar iyi kopyalayabilirler ki, bazen hangisi olduğunu anlamak zorlaşır.",
"Meşe palamudu depolarlar.",
