diet:"Avrupa kızılgerdanları etçildir. Örümcekler, solucanlar ve böcekler gibi çok çeşitli karasal omurgasızları avlarlar. Sonbahar ve kış aylarında, normal beslenmelerine ek olarak meyve ve çilek de yerler. Ayrıca kuş yemliklerine konulan tohum karışımlarını da yerler.",
about:"Kızılgerdan Avrupa'nın en sevilen ötücü kuşlarından biridir.",
behavior:"Avrupa kızılgerdanları gündüz aktif olan, ancak ay ışığında veya yapay ışık bulunan alanlarda geceleri de beslenebilen kuşlardır. Genellikle yalnız yaşarlar ve özellikle erkekler bölgelerini koruma konusunda oldukça saldırgandır. Bölgelerine giren rakipleri uzaklaştırmak için agresif davranışlar sergileyebilirler. Kızılgerdanlar çeşitli sesler kullanarak iletişim kurar; alarm durumlarında kısa çağrılar çıkarırken, üreme döneminde melodik ve flüt benzeri şarkılar söylerler. Hem erkekler hem de dişiler kış aylarında da ötüşlerini sürdürürler. Erkekler çoğu zaman aynı bölgeyi yıl boyunca korurken, dişiler mevsimsel olarak kısa mesafeli yer değişiklikleri yapabilir. Güçlü bölge savunmaları ve etkileyici ötüşleriyle Avrupa'nın en tanınan kuş türlerinden biridir.",
distribution:"Avrupa, Batı Asya ve Kuzey Afrika'da yaşamaktadır.",
