" Avrupa kızılgerdanları, insanlardan nispeten korkmaz ve toprak kazma gibi insan faaliyetlerine ilgi duyarlar; bu faaliyetler, solucanları ve yeni ortaya çıkan diğer yiyecekleri aramak içindir. Kızılgerdan, bahçıvanın dostu olarak kabul edilir ve çeşitli halk inanışları nedeniyle bu kuşa asla zarar verilmez.",
