behavior:"Jabirular gündüzleri aktiftir ve sosyaldirler. Çoğu zamanlarını av arayarak geçirdikleri su kaynaklarının yakınında büyük gruplar halinde yaşarlar. Sürüler halinde beslenirler ve genellikle sığ sularda yürüyerek avlanırlar. Jabirular avlarını görme duyusundan çok dokunma duyusuyla tespit ederler. Açık gagalarını suya 45 derecelik bir açıyla tutarak beslenirler. Avla temas ettiklerinde, leylekler gagalarını kapatır, avı sudan çıkarır ve yutmak için başlarını geriye atarlar. Jabirular fırsatçı avcılardır. Bir örnekte, tarım alanında ev farelerinin popülasyonunda patlama yaşandığında, her tarlada yüzlerce jabiru'nun kemirgenlerle beslendiği görülmüştür (her yerde nadiren büyük sayılarda görülen bir kuş için alışılmadık bir durum). Nadir durumlarda, jabiruların birlikte yaşadıkları iki küçük leylek türü olan Orman leyleği ve Maguari leyleğinden av çalmaya çalıştıkları görülmüştür.",
distribution:"Orta ve Güney Amerika'da yaşamaktadır. Jabiru kuşları göç etmez ve yıl boyunca sulak alanlarda, nehir kıyılarında, bataklıklarda, su basmış alanlarda ve pirinç tarlalarında yaşarlar.",
