about:"Küçük flamingo dünyadaki en kalabalık flamingo türüdür.",
behavior:"Küçük flamingolar göç etmezler ve bazen 1 milyondan fazla kuştan oluşan büyük koloniler halinde yaşarlar. Çoğunlukla gece aktiftirler. Besin kaynakları tükendiğinde, büyük, V şeklinde oluşumlar halinde su kütleleri arasında uçarlar. Besin bol olduğunda bile, sürüler bazen gündüzleri de su kaynakları arasında uçabilir. Küçük flamingoların koku alma duyusu yoktur ve tat alma duyuları da çok azdır. Görme duyusu grup aktiviteleri için önemlidir. İletişim kurmak için kanatlarının arka tüylerini parlatırlar. İşitme de hem yetişkinler arasında hem de yavrular ve ebeveynler arasında iletişimde önemli bir rol oynar. Yetişkinler yavrularını çıkardıkları seslerden tanıyabilirler. Bu kuşlar genellikle daha büyük gruplar içinde alt gruplar oluştururlar.",
