diet:"Kutup sumruları etçildir (balıkçıldır). Bu kuşlar küçük balık türleri (kum balığı, kum yılan balığı ve kapelin) ve kerevitlerle beslenirler.",
about:"Kutup sumrusu her yıl Kuzey Kutbu ile Antarktika arasında göç eden olağanüstü bir kuştur.",
behavior:"Kutup sumruları çok iletişimci ve sosyal hayvanlardır: her yıl aynı yerde yuva yapmak için bir araya gelirler ve büyük gruplar oluştururlar. Yuvalama alanlarını şiddetle savunurlar ve yuvalarını birbirine yakın inşa ederler. Bu kuşlar, Arktik yazından Antarktika'ya göç ettikleri için sürekli yaz mevsiminde yaşarlar ve bu nedenle en çok güneş ışığını görürler. Arktik sumrular gündüz aktiftirler. Yiyecek ararken bir süre yukarı doğru uçarlar ve ardından havada asılı kalarak su yüzeyinde av ararlar. Uzun mesafeli göçleri sırasında Arktik sumrular, dinlenmek için doğrudan suyun üzerinde veya yüzen kütüklerin üzerinde dururlar.",
