distribution:"Kel kartallar, kuzey Meksika'dan ABD ve Kanada'ya kadar uzanan geniş bir bölgede yaşar ve böylece Kuzey Amerika'nın büyük bir bölümünü kapsar. Bu kuşlar, bulundukları yere bağlı olarak kısmen göçmendir.",
