behavior:"Ayakkabı gagalı kuşlar yavaş hareketleri ve uzun süre hareketsiz kalabilmeleriyle tanınır; bu nedenle sık sık “heykel gibi” olarak tanımlanırlar. Genellikle yalnız yaşar ve çamurlu sulak alanlarda tek başlarına avlanırlar. Avlarını yakalamak için büyük ölçüde keskin görme duyularına güvenir, uzun süre sabırla bekledikten sonra ani ve güçlü bir saldırı gerçekleştirirler. Beslenirken yavaş ve dikkatli hareket eder, bazen büyük gagalarıyla çamuru kazarak saklanan avlarını ortaya çıkarırlar. İnsanlara karşı hassas olsalar da yoğun bitki örtüsü bulunan alanlarda daha sakin davranabilirler. Normalde sessiz kuşlar olmalarına rağmen, özellikle üreme döneminde gagalarını birbirine vurarak ve çeşitli sesler çıkararak iletişim kurarlar. Yavrular ise yiyecek isterken hıçkırığa benzeyen dikkat çekici sesler çıkarırlar.",
