behavior:"İmparator penguenler yıl boyunca Güney Okyanusu'nun zorlu koşullarında yaşayan, sosyal kuşlardır. Büyük koloniler halinde bir araya gelir ve özellikle üreme döneminde güçlü bir iş birliği sergilerler. Soğuk hava koşullarında vücut ısılarını korumak için birbirlerine sokularak kümelenirler. Yetişkinler, üreme ve beslenme alanları arasında düzenli olarak uzun yolculuklar yaparlar. Suda son derece çevik ve güçlü yüzücülerdir; avlarını yakalamak için derin dalışlar gerçekleştirebilirler. Karada ise kendilerine özgü sallanarak yürür veya karınlarının üzerinde kayarak ilerlerler. Dayanıklılıkları ve zorlu kutup koşullarına uyum sağlama yetenekleriyle tanınırlar.",
distribution:"İmparator penguenleri, Antarktika kıtasının kıyı şeridi boyunca ve sıkıştırılmış buzlarında yaygın olarak bulunur. Neredeyse her zaman kıyıya yakın ve kıyıdan 18 km (11 mil) açıkta bulunan sağlam buz kütleleri üzerinde ürerler. Üreme kolonileri genellikle buz uçurumlarının ve buzdağlarının rüzgardan bir miktar koruma sağladığı alanlarda bulunur.",
facts:[
"Dünyanın en büyük penguenidir.",
"Erkekler yumurtaları korur.",
"-40°C sıcaklıklara dayanabilir.",
"İmparator penguenler mükemmel yüzücüler ve harika dalgıçlardır. 500 metreye kadar derinliğe dalabilirler ve yaklaşık 22 dakika su altında kalabilirler.",
"Bu kuşların gözlerinin arkasında, kanlarını tuzdan arındıran bir filtre görevi gören özel bir supraorbital bez bulunur. Bu bez sayesinde penguenler avlanırken tuzlu okyanus suyunu yutabilirler; tuz daha sonra filtrelenir ve hayvanın gagası yoluyla veya hapşırma yoluyla dışarı atılır.."
],
