behavior:"Sakallı akbabalar geniş bölgelerde yaşayan ve genellikle çiftler halinde görülen yırtıcı kuşlardır. Gündüz aktif olan bu kuşlar, yiyecek aramak için saatlerce havada süzülebilirler. Beslenmelerinin büyük bölümünü kemikler oluşturur ve güçlü sindirim sistemleri sayesinde kemikleri kolayca parçalayabilirler. Yutamayacakları kadar büyük kemikleri ise yüksekten kayalara bırakarak kırar ve içlerindeki besleyici kemik iliğine ulaşırlar. Bu sıra dışı davranış, hayvanlar alemindeki en dikkat çekici beslenme stratejilerinden biridir. Genç bireylerin bu tekniği ustalaşarak öğrenmesi yıllar sürebilir. Sakallı akbabalar zaman zaman küçük canlı avları da yakalayabilir, ancak çoğunlukla leşlerle beslenirler. Yavrularını beslemek için diğer akbabalardan farklı olarak yiyecekleri kursaklarında taşıyarak yuvaya götürürler.",
