about:"Beyaz leylek Avrupa'nın en tanınmış göçmen kuşlarından biridir.",
behavior:"Beyaz leylekler sosyal ve bölgeci olmayan kuşlardır. Üreme döneminde birbirlerinden belirli bir mesafe bırakarak küçük koloniler halinde yuva yaparlar, diğer zamanlarda ise daha büyük sürüler oluştururlar. Göç sırasında ve kışlama alanlarında yüzlerce hatta binlerce bireyin bir araya geldiği kalabalık gruplar görülebilir. Gündüz aktif olan bu kuşlar, çoğunlukla açık çayırlarda ve kısa bitki örtüsüne sahip alanlarda avlanırlar. Küçük avlarını bütün olarak yutarken, daha büyük avlarını parçalayarak tüketirler. Beyaz leylekler iletişim kurmak için en çok gagalarını birbirine vurduklarında çıkan karakteristik takırtı sesini kullanırlar. Yetişkinler nadiren ses çıkarırken, yavrular tıslama, cıvıldama ve miyavlamaya benzer seslerle iletişim kurabilirler.",
distribution:"Avrupa, Batı Asya ve Afrika'da yaşamaktadır.  Beyaz leylekler, uzun ot ve çalılıklarla kaplı alanlardan kaçınarak, otlaklar, tarım alanları, meralar, bozkırlar, savanlar ve sığ sulak alanlarda beslenmeyi tercih ederler.",
