behavior:"Küçük mavi penguenler hem gündüz hem de gece aktiftir. Genellikle gündüzleri denizde yiyecek arar, yavrularını besler ve geceleri yuvanın yanında uyumak için kendilerini düzenlerler. Denizden kıyıya dönerken, bu hayvanlar genellikle gruplar halinde yuvalama alanlarına doğru yürürler. Başarılı üreme yıllarında, iyi organize olmuş gruplar halinde toplanırlar ve yuvalama alanlarına gidiş ve dönüş yollarında aynı bireylerle birlikte yürürler. Küçük mavi penguenler son derece gürültülü hayvanlardır ve her bireyin kendine özgü bir sesi vardır. Çeşitli durumlarda çok çeşitli sesler kullanırlar: kur yapma sırasında, bölgeyi savunurken, bir araya gelirken, saldırganlık gösterirken veya bir bireyi tanımlamanın bir yolu olarak.",
