behavior:"Anhingalar gündüz aktif olan ve çoğunlukla yalnız yaşayan su kuşlarıdır. Zamanlarının büyük bölümünü sularda balık avlayarak geçirir, dinlenmek için ise ağaçlara veya yüksek tünek alanlarına çıkarlar. Üreme döneminde kendi türleriyle ve diğer su kuşlarıyla birlikte koloniler halinde yuvalanabilirler. Bölgeci davranışlar sergileyen bu kuşlar, yuvalarını korumak için kanatlarını açma ve gagalarını şaklatma gibi tehdit gösterileri yaparlar. Avlarını su altında takip ederek yakalar ve güçlü yüzme yeteneklerinden yararlanırlar. Islanan tüyleri nedeniyle sık sık güneşlenerek kanatlarını açar ve vücut sıcaklıklarını korumaya çalışırlar. Genellikle sessiz olsalar da gerektiğinde tıklama, homurdanma ve gıcırtıya benzer seslerle iletişim kurabilirler.",
distribution:"Kuzey ve Güney Amerika'da yaşamaktadır.  Anhingalar tropikal ve subtropikal bölgelerde yaşarlar. Tatlı veya acı su olan sıcak sığ suları tercih ederler ve bazen kıyılarda da bulunabilirler. ",
facts:[
"Yılan kuşu olarak da bilinir.",
"Su altında ustaca avlanır.",
"Erkek ve dişi anhingalar kolayca ayırt edilebilir; erkeklerin başı ve boynu siyah, dişilerin ise altın kahverengidir.",
"Anhinga ebeveynleri, yavrularını ilk olarak kusmuk yoluyla çıkardıkları balık ve sıvıyı doğrudan açık gagalarına damlatarak beslerler. Yavrular büyüdüklerinde, yiyeceği almak için başlarını ebeveynlerinin gagalarına sokarlar.",
"Anhingaların boyunlarındaki omurlar, keskin gagalarıyla balık avlamak için ihtiyaç duydukları güçlü saplamaları yapmalarına olanak tanıyan bir yapıya sahiptir.",
"Anhingalar sıklıkla başımızın üzerinde yükseklerde süzülürken görülürler. Zarif uçuculardır ve tıpkı hindi akbabasının uçuşuna benzer şekilde, kanatlarını çırpmaya gerek duymadan uzun mesafeler uçabilirler."
],
