distribution:"Görkemli quetzal kuşları, Meksika'nın Chiapas bölgesinden batı Panama'ya kadar uzanan bir alanda bulunur. Nemli yağmur ormanlarında ve dağlık bulut ormanlarında yaşarlar, ancak bitki örtüsüyle kaplı vadilerde ve seyrek ağaçlı ve otlaklı açık alanlarda da bulunabilirler. ",
