distribution:"Kuzey Avrupa ve Asya'da yaşamaktadır. Ötücü kuğular tatlı su havuzlarının, göllerin, sığ nehirlerin, bataklıkların ve sazlıkların kıyılarında ürerler. Su üstü bitki örtüsüne sahip habitatları tercih ederler ve bu, yuvaları ve yeni doğan yavruları için ek koruma sağlayabilir.",
