behavior:"Aldabra dev kaplumbağaları en çok sabahın erken saatlerinde ve akşam üzeri aktiftir. Günün sıcak saatlerini ise gölgede, çamur çukurlarında, mağaralarda veya su birikintilerinde dinlenerek geçirirler. Serinlemek için sık sık çamura girer ve vücut sıcaklıklarını bu şekilde dengelerler. Hem yalnız yaşayabilir hem de besinin bol olduğu alanlarda küçük gruplar halinde bulunabilirler. Tehlike hissettiklerinde başlarını ve uzuvlarını kabuklarının içine çekerek kendilerini korurlar. Beslenirken boyunlarını tamamen uzatarak otlar ve bazen daha yüksek bitkilere ulaşmak için ağaçlara yaslanırlar. Bu kaplumbağalar mevsimsel hareketler gösterir; kurak dönemde farklı yaşam alanlarına yayılırken, yağmurların başlamasıyla birlikte açık otlaklara ve kıyı çalılıklarına yönelirler. Yavaş hareket etmelerine rağmen çevre koşullarına uyum sağlama konusunda oldukça başarılıdırlar.",
distribution:"Seyşeller'deki Aldabra Atolü'nde yaşamaktadır. . Bu hayvanlar karasaldır ve mangrov bataklıkları, çalılık ormanları ve kıyı plajları ve kumulları da dahil olmak üzere, her birinin kendine özgü bitki örtüsü olan çok çeşitli habitatlarda yaşarlar.",
