behavior:"Sheltopusikler genellikle yalnız yaşayan ve gündüz aktif olan sürüngenlerdir. Özellikle yağışlı havalarda daha hareketli olurlar; bu dönemlerde en sevdikleri avlar olan salyangoz ve sümüklüböcekleri ararlar. Zamanlarının büyük bölümünü yerde yiyecek arayarak ve güneşlenerek geçirirler. Tehlike hissettiklerinde tıslayabilir, ısırabilir ve kötü kokulu salgılar bırakarak kendilerini savunabilirler. Diğer bazı kertenkele türlerine göre kuyruklarını bırakma eğilimleri daha düşük olsa da, gerektiğinde kuyruk ototomisi gerçekleştirebilirler. Kopan kuyruk bir süre hareket etmeye devam ederek yırtıcıların dikkatini dağıtır. Zamanla yeniden büyüyen kuyruk genellikle daha kısa ve koyu renkli olur. Bu özellikleri nedeniyle sheltopusikler, halk arasında 'cam kertenkele' olarak da bilinirler.",
distribution:"Doğu Avrupa ve Batı Asya'da yaşamaktadır. Kuru habitatları tercih ederler ve kısa otlaklar, seyrek ağaçlı tepeler, bitki örtülü kayalık yamaçlar, dağ etekleri, nehir vadileri, çalılıklar veya insan yerleşim yerlerinin yakınları gibi açık alanlarda yaşarlar.",
